def timed(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        print("->", fn.__name__)
        result = fn(*args, **kwargs)
        print("<-", fn.__name__)
        return result

    return wrapper


@timed
def work(n):
    return n * 2


